def calc(expr: str) -> int:
    import re

    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while True:
            t, _ = peek()
            if t in ('+', '-'):
                consume()
                right = parse_term()
                if t == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := unary (('*' | '/') unary)*
        left = parse_unary()
        while True:
            t, _ = peek()
            if t in ('*', '/'):
                consume()
                right = parse_unary()
                if t == '*':
                    left = left * right
                else:
                    # Integer division truncating toward zero
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    q = abs(left) // abs(right)
                    if (left < 0) != (right < 0):
                        q = -q
                    left = q
            else:
                break
        return left

    def parse_unary():
        # unary := '-' unary | power
        t, _ = peek()
        if t == '-':
            consume()
            return -parse_unary()
        return parse_power()

    def parse_power():
        # power := atom ('^' power)?  (right-associative)
        base = parse_atom()
        t, _ = peek()
        if t == '^':
            consume()
            exp = parse_power()
            return base ** exp
        return base

    def parse_atom():
        # atom := NUM | '(' expr ')'
        t, v = peek()
        if t == 'NUM':
            consume()
            return v
        if t == '(':
            consume()
            val = parse_expr()
            t2, _ = peek()
            if t2 != ')':
                raise ValueError("Expected ')'")
            consume()
            return val
        raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result
