def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
            "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def two_digits(num: int) -> str:
        if num < 20:
            return ones[num]
        t = num // 10
        o = num % 10
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    def three_digits(num: int) -> str:
        parts = []
        h = num // 100
        rest = num % 100
        if h:
            parts.append(f"{ones[h]} hundred")
        if rest:
            parts.append(two_digits(rest))
        return " ".join(parts)

    result = []
    million = n // 1_000_000
    n %= 1_000_000
    thousand = n // 1_000
    n %= 1_000

    if million:
        result.append(f"{three_digits(million)} million")
    if thousand:
        result.append(f"{three_digits(thousand)} thousand")
    if n:
        result.append(three_digits(n))

    return " ".join(result)
